input.sparql:
SELECT ?zone ?zoneName ?tsid ?seriesId WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?zoneName . }
  ?s brick:hasProperty ?p .
  ?p a brick:Air_Temperature .
  ?p ref:hasTimeseriesId ?seriesId .
}

SELECT ?point ?zone ?zoneLabel ?ref WHERE {
  ?point a brick:Zone_Air_Temperature_Sensor .
  ?point brick:isPointOf ?zone .
  OPTIONAL { ?zone rdfs:label ?zoneLabel . }
  OPTIONAL { ?point ref:hasExternalReference ?ref . }
}

SELECT ?point ?ref ?tsid WHERE {
  ?point a brick:Zone_Air_Temperature_Sensor .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}
